  "headline": "FDA's records trace our argatroban supply to a plant classified OAI 258 days before the posting",
  "headline_cites": ["E11", "E13"],
  "sentences": [
    {
      "text": "Both Corvale East and Corvale General stock argatroban labeled by Eugia US LLC and manufactured at Eugia Pharma Specialities Limited (FEI 3008461619) in India.",
      "cites": ["E1", "E3", "E13"]
    },
    {
      "text": "FDA inspected that plant on 2024-02-02 and classified the inspection OAI, with the classification known on 2024-05-02.",
      "cites": ["E9"]
    },
    {
      "text": "FDA issued a Warning Letter to the plant on 2024-08-15.",
      "cites": ["E12"]
    },
    {
      "text": "FDA inspected the plant again on 2026-02-06 and classified that inspection OAI, with the classification known on 2026-09-21.",
      "cites": ["E11"]
    },
    {
      "text": "The most recent OAI classification occurred 258 days before today's posting date of 2026-10-21.",
      "cites": ["E11"]
    },
    {
      "text": "Corvale General holds 160 units at 9.7 per day (17 days on hand) and can spare 24 units while retaining a two-week supply.",
      "cites": ["D2"]
    },
    {
      "text": "Transferring 24 units from Corvale General to Corvale East would raise Corvale East from 10 days to 11 days on hand.",
      "cites": ["D1", "D2"]
    }
  ]
}
